CREATE TABLE IF NOT EXISTS campo_record_labels(tree_id TEXT PRIMARY KEY, classification TEXT NOT NULL DEFAULT '' CHECK(classification IN ('','homologacao','producao')), revision INTEGER NOT NULL DEFAULT 1, updated_at TEXT NOT NULL, actor TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS campo_record_label_changes(seq INTEGER PRIMARY KEY AUTOINCREMENT, tree_id TEXT NOT NULL, classification TEXT NOT NULL, previous_classification TEXT, revision INTEGER NOT NULL, updated_at TEXT NOT NULL, actor TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS campo_record_labels_class ON campo_record_labels(classification);
CREATE TRIGGER IF NOT EXISTS campo_label_insert AFTER INSERT ON campo_record_labels BEGIN INSERT INTO campo_record_label_changes(tree_id,classification,previous_classification,revision,updated_at,actor) VALUES(NEW.tree_id,NEW.classification,NULL,NEW.revision,NEW.updated_at,NEW.actor); END;
CREATE TRIGGER IF NOT EXISTS campo_label_update AFTER UPDATE ON campo_record_labels WHEN NEW.classification IS NOT OLD.classification BEGIN INSERT INTO campo_record_label_changes(tree_id,classification,previous_classification,revision,updated_at,actor) VALUES(NEW.tree_id,NEW.classification,OLD.classification,NEW.revision,NEW.updated_at,NEW.actor); END;
